/**
 * 
 * @param {*} req 
 * @returns 
 */
async function getRecentResult(workspace, req) {
    try {
        console.log(`${_module} [ getRecentResult ]`, workspace)
        let gpt_recent = workspace.hasOwnProperty("gpt_recent_results") ? workspace["gpt_recent_results"] : []
        gpt_recent.forEach(async (cr_set) => {
            await cr_set.forEach(async (cr) => {
                let nodePairs = [...cr.label.split(/-+>?/g)]
                let cause = await nodePairs[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                let effect = await nodePairs[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                await updateSublabel(cause, effect, req.query.nn, cr)
            })
        })
        return gpt_recent
    }
    catch (exception) {
        console.log(`${_module} [ getRecentResult ]exception `, exception)
        return exception
    }
}

async function updateSublabel(cause, effect, nn, cr) {
    try {
        if (nn !== undefined) {
            let causeId = nn.hasOwnProperty(cause) ? nn[cause] : undefined
            let effectId = nn.hasOwnProperty(effect) ? nn[effect] : undefined
            console.log(`${_module} [ updateSublabel ]cause ${cause}, causeId ${causeId}, effect ${effect}, effectId ${effectId}\'`)
            if (causeId !== undefined) {
                let causeNode = runtime._.nodes.getNode(causeId)
                let actuallyAdded = false
                if (causeNode !== undefined && causeNode !== null) {
                    if (causeNode.wires !== undefined) {
                        causeNode.wires[0].forEach(wire => {
                            if (wire === effectId) { actuallyAdded = true }
                        })
                    }
                    cr.sublabel = actuallyAdded ? "added" : ""
                }
            } else {
                cr.sublabel = ""
                cr.label = cause + "->" + effect
            }
        } else {
            cr.sublabel = ""
            cr.label = cause + "->" + effect
        }
    } catch (exception) {
        console.log(`${_module} [ updateSublabel ] `, exception)
        throw exception
    }
}

/**
 * Get prompt info 
 * @param {*} req 
 * @param {*} res 
 * @returns 
 */
async function getPromptInfo(req, res) {
    try {
        console.log(`${_module} [ getPromptInfo ] req `, req.query)
        // match typedb first 
        let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${req.query.activeWorkspace}\"; get $gpt_info;`
        let opts = {
            "db": "causeway-repo",
            "query": match_gpt_info,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ"
        }
        let query_result = await typedbApi.executeQuery(opts)
        console.log(`${_module} [ getPromptInfo ] query_result`, query_result)
        let return_object = {
            "gpt_research_question": "",
            "gpt_prompt": "",
            "gpt_recent_results": "",
        }
        let workspace = {}
        let researchQuestion = ""
        let prompt = ""
        let gpt_info = ["", ""]
        let recent_result = ""
        let keys = new Set(["gpt_research_question", "gpt_prompt", "gpt_recent_results", "gpt_api_key", "gpt_api_org"])
        let transaction = await typedbApi.create_transaction(opts.transaction_type)
        if (query_result.length !== 0) {
            let _gpt_info = query_result[0].get("gpt_info").asRemote(transaction)
            let _gpt_info_attributes = await _gpt_info.getHas().collect()
            for await (let attribute of _gpt_info_attributes) {
                let _label = attribute.type.label.name
                let attr_value = attribute.value
                if (keys.has(_label)) {
                    if (_label === "gpt_research_question") { researchQuestion = attr_value }
                    if (_label === "gpt_prompt") { prompt = attr_value }
                    if (_label === "gpt_recent_results") {
                        attr_value = attr_value.replaceAll(/\'/g, "\"")
                        recent_result = await JSON.parse(attr_value)
                        for await (let result of recent_result[0]) {
                            let node_pair = result.label.split(/-+>?/g)
                            console.log("node pairs: ", node_pair)
                            let cause = node_pair[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                            let effect = node_pair[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                            result.checkbox = true
                            result.selected = false
                            result.collapsible = true
                            await updateSublabel(cause, effect, req.query.nn, result)
                        }
                    }
                    if (_label === "gpt_api_key") { gpt_info[0] = attr_value }
                    if (_label === "gpt_api_org") { gpt_info[0] = attr_value }
                }
            }
        } else {
            console.log(`${_module} [ gpt_info ] gpt_info does not exist`)
            workspace = await getWorkspaceContext(req)
            researchQuestion = await getResearchQuestion(workspace)
            prompt = await getPrompt(workspace)
            gpt_info = await getGPTInfo(workspace)
            recent_result = await getRecentResult(workspace, req)
        }
        await typedbApi.close_transaction(opts.transaction_type, transaction)
        res.status(200).send({ researchQuestion: researchQuestion, prompt: prompt, gptInfo: gpt_info, gpt_recent_results: recent_result })
        return
    } catch (exception) {
        console.log(`${_module} getPromptInfo exception `, exception)
        res.status(500).send({ error: exception })
    }
}


/** 
 * process response from ChatGPT
 */
async function processGPTAnswer(answer) {
    try {
        var nodePairSet = await answer.map(response => {
            let digraph = response.text.replaceAll("+", "").replaceAll("\'", "")
            // split digraph into sub array
            let substrings = digraph.split("\n")
            let nodes = {}
            let relations = new Set()
            if (substrings !== undefined) {
                substrings.forEach(string => {
                    // identify statement type
                    // node statement
                    if (string.includes("label")) {
                        console.log("Node statement: ", string)
                        let _node = string.split("[")
                        let node_id = _node[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        let label = _node[1]
                            .match(/(?:"[^"]*"|^[^"]*$)/)[0]
                        nodes[node_id] = label
                        console.log(nodes)
                    }
                    // edge 
                    console.log("string", string)
                    let edge_string = string.match(/-+>?/g) ? string.match(/-+>?/g) : []
                    console.log(edge_string.length)
                    console.log("Edge Statement", edge_string)
                    if (edge_string.length > 0) {
                        let node_pair = string.split(/-+>?/g)
                        console.log("node pairs: ", node_pair)
                        let cause = node_pair[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        let effect = node_pair[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        if (effect.includes("label")) {
                            effect = effect.split("[")[0].replaceAll(" ", "")
                        }
                        let causeName = nodes[cause] ? nodes[cause] : cause
                        let effectName = nodes[effect] ? nodes[effect] : effect
                        console.log("\tcause in relation : ", causeName)
                        console.log("\teffect in relation ", effectName)

                        causeName = causeName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        effectName = effectName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        relations.add(causeName + "->" + effectName)
                    }
                })
            }
            let nodePairs = Array.from(relations).map(relation => {
                // prepare item to be added to list as disction
                let node = {
                    "label": relation,
                    "checkbox": true, // (optional) if present, display checkbox accordingly
                    "selected": false, // (optional) whether the item is selected or not
                    "collapsible": true, // prevent a parent item from being collapsed. default true.
                    "sublabel": ""
                }
                return node
            })
            return nodePairs
        })
        console.log(`${_module} processGPTAnswer nodePairSets `, nodePairSet)
        return nodePairSet
    } catch (exception) {
        console.log(`${_module} processGPTAnswer exception `, exception)
        throw exception
    }
}

async function updateWorkspaceContext(id, workspace) {
    console.log(`${_module} updateWorkspaceContext `, id, workspace)
    let ctx = await runtime.causeway.getContext(id)
    let flow = runtime._.nodes.getFlow(id)
    if (flow === null || flow === undefined) { flow = {} }
    for await (let key of Object.keys(workspace)) {
        flow[key] = workspace[key]
    }
    await ctx.set(id, workspace)
    return flow

}
async function fetchGptResponse(req, res) {
    try {
        var answer = ""
        let workspace = await getWorkspaceContext(req)
        if (!req.query.api_key.includes("...")) { workspace["gpt_api_key"] = req.query.api_key }
        if (!req.query.api_org.includes("...")) { workspace["gpt_api_org"] = req.query.api_org }
        const configuration = new Configuration({
            apiKey: workspace["gpt_api_key"],
            // organization: workspace["gpt_api_org"]
        })
        const openai = new OpenAIApi(configuration)
        console.log(`${_module} [ fetchGptResponse ] sending fetch to GPT`)
        const response = await openai.createCompletion({
            model: "text-davinci-003",
            prompt: `You are an expert system of causal reasoning. \n${req.query.prompt}`,
            n: 1,
            // stop: "\n",
            max_tokens: 575,
        })
        var answer = response.data.choices
        console.log(`${_module} [ fetchGptResponse ] answer`, answer)
        delete configuration
        delete openai
        delete response
        await postProcessGpt(req, res, answer, workspace)
    } catch (error) {
        console.log(`${_module} [ fetchGptResponse ] error`, error)
        return error
    }
}

async function postProcessGpt(req, res, answer, workspace) {
    try {
        workspace["gpt_recent_results"] = await processGPTAnswer(answer)
        let updatedFlow = await updateWorkspaceContext(req.query.activeWorkspace, workspace)
        let gpt_recent_results = JSON.stringify(workspace["gpt_recent_results"])
        gpt_recent_results = gpt_recent_results.replace(/"/g, "'")
        await updateGptInfo(req.query.activeWorkspace, "gpt_api_key", workspace["gpt_api_key"])
        await updateGptInfo(req.query.activeWorkspace, "gpt_recent_results", gpt_recent_results)
        res.status(200).send({ gpt_results: workspace["gpt_recent_results"], updatedFlow: updatedFlow })
    } catch (exception) {
        res.status(500).send({ error: exception.toString() })
    }
}

async function getNodeRedId() {
    return utilApi.util.generateId()
}
async function getAxisValue(min, max, axisValue) {
    let value = Math.ceil(Math.random() * (max - min) + min)
    console.log(`${_module} getAxisValue actual value ${axisValue} => new value ${value}`)
    return axisValue + value
}
/**
 * 
 * @param {*} node if we are adding a left node
 * @param {*} pairNode if we are adding a right node to the left node as a wire
 * @returns 
 */
async function updateNode(node) {
    node.id = await getNodeRedId()
    node.x = await getAxisValue(300, 400, 0)
    node.y = await getAxisValue(400, 500, 0)
    console.log(`${_module} updateNode node`, node)
    return node
}
async function fixPosition(leftNode, rightNode, type, flow, linksToAdd) {
    console.log(`${_module} fixposition leftNode(x,y) ${leftNode.x}, ${leftNode.y} && rightNode (x,y) ${rightNode.x}, ${rightNode.y}`)
    // update right node x and y according to leftNode
    if (type) {
        rightNode.x = await getAxisValue(175, 200, leftNode.x)
        if (rightNode.x < 0) {
            rightNode.x = 50
        }
        let increment = 25
        // temporarily update left node wires
        leftNode.wires[0].push(rightNode.id)
        let wireLengths = 0
        await flow.nodes.forEach(node => {
            if (node.id === leftNode.id) {
                wireLengths = node.wires[0].length
            }
        })
        rightNode.y = wireLengths === 1 ? leftNode.y : await getAxisValue(50, increment * wireLengths - 1, leftNode.y)
        console.log(`${_module} fixposition  updated rightNode ${rightNode.x} ${rightNode.y}`)
    } else {
        leftNode.x = await getAxisValue(-250, -200, rightNode.x)
        if (leftNode.x < 0) {
            leftNode.x = 50
        }
        let increment = 25
        // temporarily update left node wires
        console.log(`${_module} fixposition  leftNode `, leftNode)
        let totalInputs = 0
        await flow.nodes.forEach(async (node) => {
            let wires = new Set(node.wires[0])
            if (wires.has(rightNode.id)) {
                totalInputs += 1
            }
        })
        // check all new links to add ot see if positioning needs readhjusting
        let findTotalInputs = async (linksToAdd, rightNode, totalInputs) => {
            console.log(`${_module} fixposition findTotalInputs  linksToAdd`, linksToAdd)
            console.log(`${_module} fixposition findTotalInputs  rightNode`, linksToAdd)
            console.log(`${_module} fixposition findTotalInputs  totalInputs`, totalInputs)
            Object.keys(linksToAdd).forEach(async (key) => {
                let wires = new Set(linksToAdd[key])
                if (wires.has(rightNode.id)) {
                    totalInputs += 1
                }
            })
            return totalInputs
        }
        totalInputs = await findTotalInputs(linksToAdd, rightNode, totalInputs)
        console.log(`${_module} fixposition totalInputs ${totalInputs} ${totalInputs - 1 === 0}`)
        leftNode.y = totalInputs - 1 === 0 ? rightNode.y : await getAxisValue(50, 50 + increment * totalInputs - 1, rightNode.y)
        console.log(`${_module} fixposition updated leftNode ${leftNode.x}, ${leftNode.y}`)
    }
}

async function getWorkspaceContext(req) {
    let activeWorkspace = req.body.activeWorkspace ? req.body.activeWorkspace : req.query.activeWorkspace
    console.log(`${_module} getWorkspaceContext activeWorkspace ${activeWorkspace}`)
    let ctx = await runtime.causeway.getContext(activeWorkspace)
    let workspace = {}
    if (ctx !== undefined) {
        workspace = await ctx.get(activeWorkspace)
    }
    if (workspace === undefined) { workspace = {} }
    console.log(`${_module} getWorkspaceContext workspace ${Object.keys(workspace)}`)
    return workspace
}

async function addNewRelations(req, res) {
    try {
        let workspace = await getWorkspaceContext(req)
        let gpt_recent = workspace["gpt_recent_results"] ? workspace["gpt_recent_results"] : []
        let flow = await runtime._.nodes.getFlow(req.body.activeWorkspace)
        let flowId = flow.id ? flow.id : req.activeWorkspace
        let nn_exists = Object.keys(req.body).includes("nn")
        let nodesToAdd = []
        linksToAdd = {}
        let seenNodes = {}
        for await (let relation of req.body.newRelations) {
            relation = relation.split(/-+>?/g)
            let causeName = relation[0]
            let effectName = relation[1]
            let causeExists = false
            let effectExists = false
            let leftNode = {}
            let rightNode = {}
            let leftNodeId = ""
            let rightNodeId = ""
            if (nn_exists) {
                causeExists = req.body.nn[causeName] ? true : false
                leftNode = req.body.nn[causeName] ? req.body.nn[causeName] : leftNode
                effectExists = req.body.nn[effectName] ? true : false
                rightNode = req.body.nn[effectName] ? req.body.nn[effectName] : rightNode
            }
            console.log(`${_module} addNewRelations nodesToAdd.length ${nodesToAdd.length}`)

            for await (let node of nodesToAdd) {
                if (causeName === node.name) {
                    console.log("node previously added in this run")
                    leftNode = node
                    causeExists = true
                }
                if (effectName === node.name) {
                    console.log("effect node previously added in this run")
                    rightNode = node
                    effectExists = true
                }
            }
            console.log(`${_module} addNewRelations causeName ${causeName} ; causeExists ${causeExists}`)
            console.log(`${_module} addNewRelations effectName ${effectName} ; effectExists ${effectExists}`)
            if (causeExists && effectExists) {
                /**  do nothing */
                console.log(`${_module} addNewRelations [ both nodes exist]`)
                console.log(`${_module} addNewRelations leftNode ${leftNode} rightNode ${rightNode}`)

                if (linksToAdd.hasOwnProperty(leftNode)) {
                    let items = new Set(linksToAdd[leftNode])
                    if (!items.has(rightNode)) {
                        linksToAdd[leftNode].push(rightNode)
                    }
                } else {
                    linksToAdd[leftNode] = [rightNode]
                }
                console.log(`${_module} addNewRelations linksToAdd `, linksToAdd)
            } else if (causeExists) {
                /** 
                 * if the left node exists then
                 * (1) create the right node
                 * (2) update the left node by pushing the id of the right node to node wires
                 * (3) add the right node to the flow
                 * */
                // only cause node exists
                console.log(`${_module} addNewRelations [ only left node exists ]`)
                // get cause node 
                await flow.nodes.forEach(node => {
                    if (node.id === req.body.nn[causeName]) { leftNode = node }
                })
                //  (1) create rightNode
                rightNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }
                rightNode = await updateNode(rightNode)
                await fixPosition(leftNode, rightNode, true, flow, linksToAdd)

                // (2) find left node & update wires
                let causeNodeID = req.body.nn[causeName]

                // (3) add rightNode to flow
                nodesToAdd.push(rightNode)
                if (linksToAdd.hasOwnProperty(causeNodeID)) {
                    let items = new Set(linksToAdd[causeNodeID])
                    if (!items.has(rightNode.id)) {
                        linksToAdd[causeNodeID].push(rightNode.id)
                    }
                } else {
                    linksToAdd[causeNodeID] = [rightNode.id]
                }
                console.log(`${_module} addNewRelations [ only left node exists ] nodesToAdd ${nodesToAdd} linksToAdd ${linksToAdd}`)

            } else if (effectExists) {

                /** 
                 * if the right node exists then
                 * (1) create the left node and add to its wires the node red id
                 * (2) find the right node to update the left node x,y,and wires
                 * (3) add new left node to the flow's nodes
                 * */
                console.log(`${_module} addNewRelations [ only right node exists ]`)
                if (nn_exists) {
                    rightNodeId = req.body.nn.hasOwnProperty(effectName) ? req.body.nn[effectName] : rightNode.id
                } else {
                    rightNodeId = rightNode.id
                }

                //  (1) initialize left node using causeeffect json
                leftNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[rightNodeId]],
                }
                // (2) iterate the the flows nodes to find right node and update the fields x,y, and wires of the leftnode
                await flow.nodes.forEach(async (node) => {
                    if (node.id === rightNodeId) {
                        rightNode = node
                    }
                })
                leftNode = await updateNode(leftNode)
                // (3) add left node to flow nodes
                nodesToAdd.push(leftNode)
                if (linksToAdd.hasOwnProperty(leftNode.id)) {
                    let items = new Set(linksToAdd[leftNode.id])
                    if (!items.has(rightNodeId)) {
                        linksToAdd[leftNode.id].push(rightNodeId)
                    }
                } else {
                    linksToAdd[leftNode.id] = [rightNodeId]
                }
                await fixPosition(leftNode, rightNode, false, flow, linksToAdd)

            } else if (!causeExists && !effectExists) {
                /** 
                  * if neither left or right node exists
                  * (1) initialize left node
                  * (2) initialize right node
                  * (3) update nodes' x,y, and wire fields with actual values
                  * (4) add nodes to the flow
                  * */

                console.log(`${_module} addNewRelations [ Neither node exists ]`)
                // (1) initialize leftNode
                leftNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }
                // (2) initialize rightNode
                rightNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }

                // (3) update nodes x,y, and wire fields with actual values
                rightNode = await updateNode(rightNode)
                leftNode = await updateNode(leftNode)

                // update right node 
                await fixPosition(leftNode, rightNode, true, flow, linksToAdd)

                //  (4) add nodes to the flow
                nodesToAdd.push(leftNode)
                nodesToAdd.push(rightNode)
                if (linksToAdd.hasOwnProperty(leftNode.id)) {
                    let items = new Set(linksToAdd[leftNode.id])
                    if (!items.has(rightNode.id)) {
                        linksToAdd[leftNode.id].push(rightNode.id)
                    }
                } else {
                    linksToAdd[leftNode.id] = [rightNode.id]
                }
            }

            // iterate through recent results to see if relation is added
            await gpt_recent.forEach(cr_set => {
                cr_set.forEach(cr => {
                    console.log(`${_module} addNewRelations crLabel`, cr.label)
                    console.log(`${_module} addNewRelations crLabel relation`, relation[0][0])
                    if (cr.label === relation[0][0]) {
                        cr.sublabel = "added"
                    }
                })
            })
        }

        // await ctx.set("gpt_recent_results", gpt_recent)
        workspace["gpt_recent_results"] = gpt_recent
        let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
        // await ctx.set(req.body.activeWorkspace, workspace)
        // updateFlow(flowId, flow, "")
        delete seenNodes
        res.status(200).send({
            gpt_results: "ok",
            nodesToAdd: nodesToAdd,
            linksToAdd: linksToAdd,
            updatedFlow: updatedFlow
        })
    } catch (exception) {
        console.log(`${_module} addNewRelations exception`, exception)
        res.status(500).send({ error: exception })
    }
}


async function updateGptInfo(activeWorkspace, key, value) {
    let _func_name = "[updateGptInfo]"
    console.log(`${_module} ${_func_name} ==================================`)
    /* [ disconnecting from the old attribute value ]
        match $org isa organisation, has name "Medicely", has registration-number $rn; 
        delete $org has $rn;
        insert $org has registration-number "81726354";
    */
    try {
        let opts = {
            "db": "causeway-repo",
            "query": `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\", has ${key} $${key}; get $${key};`,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ"
        }
        let _result = await typedbApi.executeQuery(opts)
        console.log(`${_module} ${_func_name} _result ${key} ${_result.length} `)
        opts["transaction_type"] = "WRITE"
        // insert - update  attribute
        if (_result.length === 0) {
            console.log(`${_module} ${_func_name} inserting attribute`)
            opts["query_type"] = "insert"
            opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\";\ninsert $gpt_info has ${key} \"${value}\";`
        } else {
            console.log(`${_module} ${_func_name} updating attribute ${key}`)
            opts["query_type"] = "update"
            opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\", has ${key} $${key};\n delete $gpt_info has $${key};\ninsert $gpt_info has ${key} \"${value}\";`
        }
        await typedbApi.executeQuery(opts)
        console.log(`${_module} ${_func_name} update_gpt_info for ${key} successful ${String.fromCharCode(0x2611)} `)

    } catch (exception) {
        console.log(`${_module} ${_func_name} Exception ${String.fromCharCode(0x274C)} ${exception}`)
    }

}
