async function storeGptPromptInfo(req, res) {
    try {
        let flow = req.body
        // match the 
        let match_gpt_info_opts = {
            "db": "causeway-repo",
            "query": `match $gpt_info isa gpt_info, has nrid \"${flow.id}\";`,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ"
        }
        let gpt_info_query_result = await typedbApi.executeQuery(match_gpt_info_opts)
        let update = gpt_info_query_result.length > 0 ? true : false
        if (!update) {
            let insert_query_opts = {
                "db": "causeway-repo",
                "query": `insert $gpt_info isa gpt_info, has nrid \"${flow.id}\";`,
                "query_type": "insert",
                "session_type": "DATA",
                "transaction_type": "WRITE"
            }
            await typedbApi.executeQuery(insert_query_opts)
        }
        let gptKeys = ["gpt_prompt", "gpt_research_question"]
        for await (let key of gptKeys) {
            await updateGptInfo(flow.id, key, flow[key])
        }
        res.send(200).status("Success in storing gpt info to TypeDB")
    } catch (exception) {
        console.log(`${_module} storeGptPromptInfo throwing error`)
        res.status(500).send({ error: exception })
    }
}
